31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        prepareNewOwner(ownerFieldsDto);
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        if (owner.getRegistrationDate() == null) {
111	            owner.setRegistrationDate(LocalDate.now());
112	        }
113	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
124	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
125	        if (currentOwner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        currentOwner.setAddress(ownerFieldsDto.getAddress());
129	        currentOwner.setCity(ownerFieldsDto.getCity());
130	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
131	        currentOwner.setLastName(ownerFieldsDto.getLastName());
132	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
133	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
134	        this.clinicService.saveOwner(currentOwner);
135	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Transactional
140	    @Override
141	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        this.clinicService.deleteOwner(owner);
147	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        HttpHeaders headers = new HttpHeaders();
158	        Pet pet = petMapper.toPet(petFieldsDto);
159	        owner.setId(ownerId);
160	        pet.setOwner(owner);
161	        pet.getType().setName(null);
162	        this.clinicService.savePet(pet);
163	        PetDto petDto = petMapper.toPetDto(pet);
164	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
165	            .buildAndExpand(pet.getId()).toUri());
166	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner != null) {
174	            Pet currentPet = this.clinicService.findPetById(petId);
175	            if (currentPet != null) {
176	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
177	                currentPet.setName(petFieldsDto.getName());
178	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
179	                this.clinicService.savePet(currentPet);
180	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	            }
182	        }
183	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
189	        HttpHeaders headers = new HttpHeaders();
190	        Visit visit = visitMapper.toVisit(visitFieldsDto);
191	        Pet pet = new Pet();
192	        pet.setId(petId);
193	        visit.setPet(pet);
194	        this.clinicService.saveVisit(visit);
195	        VisitDto visitDto = visitMapper.toVisitDto(visit);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
197	            .buildAndExpand(visit.getId()).toUri());
198	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
199	    }
200	
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner != null) {
207	            Pet pet = owner.getPet(petId);
208	            if (pet != null) {
209	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    /**
216	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
217	     * The required fields are checked, the telephone and email are normalized in place, and
218	     * the resulting telephone is rejected when it already belongs to another owner. Each rule
219	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
220	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
221	     * to be mapped and saved.
222	     *
223	     * @param ownerFieldsDto the submitted owner fields, normalized in place
224	     */
225	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
226	        validateRequiredFields(ownerFieldsDto);
227	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
228	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
229	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
230	    }
231	
232	    /**
233	     * Builds the customer code assigned to a newly created owner. The code is formatted as
234	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
235	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
236	     * one more than the current number of owners. For example the seventh owner named
237	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
238	     *
239	     * @param lastName the owner's last name
240	     * @return the formatted customer code
241	     */
242	    private String nextCustomerCode(String lastName) {
243	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
244	        long sequence = this.clinicService.findAllOwners().size() + 1L;
245	        return String.format("%s-%04d", last3, sequence);
246	    }
247	
248	    /**
249	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
250	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
251	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
252	     * the names of every offending field, which the exception advice renders as a 400 response
253	     * with an {@code errors} array.
254	     *
255	     * @param ownerFieldsDto the submitted owner fields
256	     */
257	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
258	        List<String> missing = new ArrayList<>();
259	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
260	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
261	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
262	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
263	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
264	        if (!missing.isEmpty()) {
265	            throw new RequiredFieldsMissingException(missing);
266	        }
267	    }
268	
269	    private void addIfBlank(List<String> missing, String fieldName, String value) {
270	        if (value == null || value.isBlank()) {
271	            missing.add(fieldName);
272	        }
273	    }
274	
275	    /**
276	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
277	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
278	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
279	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
280	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
281	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
282	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
283	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
284	     *
285	     * @param telephone the submitted telephone value
286	     * @return the normalized E.164 telephone
287	     */
288	    private String normalizeTelephone(String telephone) {
289	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
290	        String e164;
291	        if (cleaned.startsWith("+")) {
292	            e164 = "+" + cleaned.substring(1);
293	        } else {
294	            String national = cleaned;
295	            if (national.startsWith("0")) {
296	                national = national.substring(1);
297	            }
298	            e164 = "+61" + national;
299	        }
300	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
301	            throw new InvalidFieldsException(List.of("telephone"));
302	        }
303	        return e164;
304	    }
305	
306	    /**
307	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
308	     * and a domain containing at least one dot, none of the parts holding whitespace or a
309	     * second {@code @}.
310	     */
311	    private static final java.util.regex.Pattern EMAIL_PATTERN =
312	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
313	
314	    /**
315	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
316	     * accepted and returned unchanged. When present it must be a syntactically valid address;
317	     * the value is stored and returned lower-cased. When present but invalid an
318	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
319	     * response naming the {@code email} field.
320	     *
321	     * @param email the submitted email value, or {@code null} when omitted
322	     * @return the lower-cased email, or {@code null} when none was supplied
323	     */
324	    private String normalizeEmail(String email) {
325	        if (email == null) {
326	            return null;
327	        }
328	        String trimmed = email.trim();
329	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
330	            throw new InvalidFieldsException(List.of("email"));
331	        }
332	        return trimmed.toLowerCase(java.util.Locale.ROOT);
333	    }
334	
335	    /**
336	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
337	     * The telephone is stored in its normalized E.164 form, so a plain equality check
338	     * against every owner's telephone compares E.164 values. When a match is found a
339	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
340	     * 409 Conflict response.
341	     *
342	     * @param telephone the normalized telephone of the owner being created
343	     */
344	    private void rejectDuplicateTelephone(String telephone) {
345	        boolean taken = this.clinicService.findAllOwners().stream()
346	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
347	        if (taken) {
348	            throw new DuplicateTelephoneException(telephone);
349	        }
350	    }
351	}
