38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingResult bindingResult = e.getBindingResult();
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
139	        if (bindingResult.hasErrors()) {
140	            logger.debug("Validation error at {} {}: {}",
141	                request.getMethod(),
142	                request.getRequestURI(),
143	                bindingResult.getFieldErrors());
144	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
145	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
146	                .map(FieldError::getField)
147	                .distinct()
148	                .toList());
149	        }
150	        return ResponseEntity.status(status).body(detail);
151	    }
152	
153	    /**
154	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves
155	     * blank one or more required fields. Returns a 400 Bad Request whose {@code errors}
156	     * property lists the name of each offending field.
157	     *
158	     * @param e The {@link RequiredFieldsMissingException} to be handled
159	     * @param request {@link HttpServletRequest} object referring to the current request.
160	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
161	     */
162	    @ExceptionHandler(RequiredFieldsMissingException.class)
163	    @ResponseBody
164	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
165	        HttpStatus status = HttpStatus.BAD_REQUEST;
166	        logger.debug("Missing or blank required fields at {} {}: {}",
167	            request.getMethod(),
168	            request.getRequestURI(),
169	            e.getFields());
170	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
171	        detail.setProperty("errors", e.getFields());
172	        return ResponseEntity.status(status).body(detail);
173	    }
174	
175	    /**
176	     * Handles {@link InvalidFieldsException} thrown when a request supplies one or more
177	     * fields whose value is present but fails a business rule (for example a telephone
178	     * that does not normalize to exactly ten digits). Returns a 400 Bad Request whose
179	     * {@code errors} property lists the name of each offending field.
180	     *
181	     * @param e The {@link InvalidFieldsException} to be handled
182	     * @param request {@link HttpServletRequest} object referring to the current request.
183	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
184	     */
185	    @ExceptionHandler(InvalidFieldsException.class)
186	    @ResponseBody
187	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
188	        HttpStatus status = HttpStatus.BAD_REQUEST;
189	        logger.debug("Invalid field values at {} {}: {}",
190	            request.getMethod(),
191	            request.getRequestURI(),
192	            e.getFields());
193	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
194	        detail.setProperty("errors", e.getFields());
195	        return ResponseEntity.status(status).body(detail);
196	    }
197	
198	    /**
199	     * Handles {@link DuplicateTelephoneException} thrown when a request tries to create an owner
200	     * whose normalized telephone is already used by another owner. Returns a 409 Conflict.
201	     *
202	     * @param e The {@link DuplicateTelephoneException} to be handled
203	     * @param request {@link HttpServletRequest} object referring to the current request.
204	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
205	     */
206	    @ExceptionHandler(DuplicateTelephoneException.class)
207	    @ResponseBody
208	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
209	        HttpStatus status = HttpStatus.CONFLICT;
210	        logger.debug("Duplicate telephone at {} {}: {}",
211	            request.getMethod(),
212	            request.getRequestURI(),
213	            e.getMessage());
214	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
215	        return ResponseEntity.status(status).body(detail);
216	    }
217	
218	    /**
219	     * Renders the field-level errors of a {@link BindingResult} as the {@link ValidationMessageDto} list
220	     * exposed under the {@code schemaValidationErrors} property of the response.
221	     *
222	     * @param bindingResult The {@link BindingResult} carrying the rejected fields.
223	     * @return One {@link ValidationMessageDto} per field error.
224	     */
225	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
226	        return bindingResult.getFieldErrors().stream()
227	            .map(fieldError -> {
228	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
229	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
230	                String message = "Field '%s' %s (rejected value: %s)".formatted(
231	                    fieldError.getField(),
232	                    defaultMessage,
233	                    rejectedValue);
234	                return new ValidationMessageDto(message)
235	                    .putAdditionalProperty("field", fieldError.getField())
236	                    .putAdditionalProperty("rejectedValue", rejectedValue)
237	                    .putAdditionalProperty("defaultMessage", defaultMessage);
238	            })
239	            .toList();
240	    }
